 "content": "def transform(grid):
    """Fill outlined rectangular interiors with matched-count checkerboards."""
    h, w = len(grid), len(grid[0])
    frames = []
    frame_colors = set()

    # Each frame color forms exactly one rectangular perimeter, with a blank cavity.
    for color in {v for row in grid for v in row if v != 0}:
        points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0 = min(r for r, _ in points)
        r1 = max(r for r, _ in points)
        c0 = min(c for _, c in points)
        c1 = max(c for _, c in points)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        perimeter = {
            (r, c)
            for r in range(r0, r1 + 1)
            for c in range(c0, c1 + 1)
            if r in (r0, r1) or c in (c0, c1)
        }
        if set(points) != perimeter:
            continue
        if any(grid[r][c] != 0 for r in range(r0 + 1, r1) for c in range(c0 + 1, c1)):
            continue
        frames.append((color, r0, r1, c0, c1))
        frame_colors.add(color)

    marker_counts = {}
    for row in grid:
        for value in row:
            if value != 0 and value not in frame_colors:
                marker_counts[value] = marker_counts.get(value, 0) + 1

    out = [[0 for _ in range(w)] for _ in range(h)]
    for color, r0, r1, c0, c1 in frames:
        for c in range(c0, c1 + 1):
            out[r0][c] = color
            out[r1][c] = color
        for r in range(r0, r1 + 1):
            out[r][c0] = color
            out[r][c1] = color

        # The scattered marker color is identified by the number of its pixels;
        # the intended fill is the globally even phase of a checkerboard.
        fill_count = sum(
            1
            for r in range(r0 + 1, r1)
            for c in range(c0 + 1, c1)
            if (r + c) % 2 == 0
        )
        fill_color = next((v for v, n in marker_counts.items() if n == fill_count), None)
        if fill_color is not None:
            for r in range(r0 + 1, r1):
                for c in range(c0 + 1, c1):
                    if (r + c) % 2 == 0:
                        out[r][c] = fill_color
    return out


